result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/rate_limit.py", "content": """"Fixed-window rate limiting as Flask middleware.

Limits each API key (X-API-Key header) to N requests per fixed window.
The clock is injectable so tests can advance time without sleeping.
"""

from __future__ import annotations

import threading
import time
from typing import Callable

from flask import Flask, Response, jsonify, request


class FixedWindowRateLimiter:
    """Fixed-window counter keyed by API key, with an injectable clock."""

    def __init__(
        self,
        limit: int = 10,
        window_seconds: float = 60.0,
        clock: Callable[[], float] = time.time,
    ) -> None:
        if limit < 1:
            raise ValueError("limit must be >= 1")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be > 0")
        self.limit = limit
        self.window_seconds = window_seconds
        self.clock = clock
        # key -> window_start -> count
        self._buckets: dict[str, dict[int, int]] = {}
        self._lock = threading.Lock()

    def _current_window(self) -> int:
        return int(self.clock() // self.window_seconds)

    def check(self, key: str) -> tuple[bool, int]:
        """Try to consume one slot for `key`.

        Returns (allowed, retry_after_seconds). retry_after is 0 when allowed;
        otherwise it is the whole seconds until the current window resets
        (rounded up, always >= 1 so clients never see a useless 0).
        """
        now = self.clock()
        window = int(now // self.window_seconds)
        with self._lock:
            buckets = self._buckets.setdefault(key, {})
            # Drop stale windows to keep memory bounded.
            for stale in [w for w in buckets if w != window]:
                del buckets[stale]
            count = buckets.get(window, 0)
            if count >= self.limit:
                boundary = (window + 1) * self.window_seconds
                retry_after = max(1, -(-(boundary - now) // 1))  # ceil, min 1s
                return False, int(retry_after)
            buckets[window] = count + 1
            return True, 0

    def reset(self) -> None:
        with self._lock:
            self._buckets.clear()


def register_rate_limiter(
    app: Flask,
    limiter: FixedWindowRateLimiter | None = None,
    header: str = "X-API-Key",
    exempt_paths: tuple[str, ...] = ("/health",),
) -> FixedWindowRateLimiter:
    """Attach fixed-window rate limiting middleware to a Flask app."""
    limiter = limiter or FixedWindowRateLimiter()

    @app.before_request
    def _rate_limit() -> Response | None:
        if request.path in exempt_paths:
            return None
        api_key = request.headers.get(header)
        if not api_key:
            return (
                jsonify({"error": {"code": "missing_api_key"}}),
                401,
            )
        allowed, retry_after = limiter.check(api_key)
        if not allowed:
            resp = jsonify({"error": {"code": "rate_limited"}})
            resp.status_code = 429
            resp.headers["Retry-After"] = str(retry_after)
            return resp
        return None

    return limiter


def create_app(
    limit: int = 10,
    window_seconds: float = 60.0,
    clock: Callable[[], float] | None = None,
) -> Flask:
    """App factory; pass a fake clock for tests."""
    app = Flask(__name__)
    limiter_kwargs: dict = {"limit": limit, "window_seconds": window_seconds}
    if clock is not None:
        limiter_kwargs["clock"] = clock
    register_rate_limiter(app, FixedWindowRateLimiter(**limiter_kwargs))

    @app.get("/health")
    def health() -> Response:
        return jsonify({"status": "ok"})

    @app.get("/resource")
    def resource() -> Response:
        return jsonify({"data": "ok"})

    return app
"})
