import pytest

from rate_limit import FixedWindowRateLimiter, create_app


class FakeClock:
    """Controllable clock: no sleeping, tests drive time explicitly."""

    def __init__(self, start: float = 1_000_000.0) -> None:
        self.now = start

    def __call__(self) -> float:
        return self.now

    def advance(self, seconds: float) -> None:
        self.now += seconds


@pytest.fixture()
def clock() -> FakeClock:
    return FakeClock()


@pytest.fixture()
def client(clock: FakeClock):
    app = create_app(limit=10, window_seconds=60.0, clock=clock)
    app.config["TESTING"] = True
    with app.test_client() as c:
        yield c


def _get(client, key: str = "key-a"):
    return client.get("/resource", headers={"X-API-Key": key})


def test_allows_exactly_ten_requests_per_window(client):
    for i in range(10):
        resp = _get(client)
        assert resp.status_code == 200, f"request {i + 1} unexpectedly limited"
        assert resp.get_json() == {"data": "ok"}


def test_eleventh_request_is_rate_limited(client):
    for _ in range(10):
        assert _get(client).status_code == 200
    resp = _get(client)
    assert resp.status_code == 429
    assert resp.get_json() == {"error": {"code": "rate_limited"}}
    assert "Retry-After" in resp.headers


def test_retry_after_is_sane_and_counts_down_to_reset(client, clock):
    for _ in range(10):
        _get(client)
    # Window started at t=1_000_000.0, resets at 1_000_060. We're at the very
    # start of the window, so nearly the full 60s remain.
    full = _get(client)
    assert full.status_code == 429
    assert int(full.headers["Retry-After"]) == 60

    clock.advance(59.5)
    late = _get(client)
    assert late.status_code == 429
    remaining = int(late.headers["Retry-After"])
    assert 1 <= remaining <= 1  # 0.5s left -> ceil -> 1


def test_advancing_clock_past_boundary_readmits_client(client, clock):
    for _ in range(10):
        assert _get(client).status_code == 200
    assert _get(client).status_code == 429

    clock.advance(60.0)  # cross into the next fixed window
    resp = _get(client)
    assert resp.status_code == 200
    # Fresh window has its own full budget of 10.
    for _ in range(9):
        assert _get(client).status_code == 200
    assert _get(client).status_code == 429


def test_separate_keys_do_not_share_buckets(client):
    for _ in range(10):
        assert _get(client, "key-a").status_code == 200
    # key-a is exhausted...
    assert _get(client, "key-a").status_code == 429
    # ...but key-b still has its own full budget.
    for _ in range(10):
        assert _get(client, "key-b").status_code == 200
    assert _get(client, "key-b").status_code == 429
    # Exhausting one key never affects the other's counters mid-window.
    clock_probe = client.get("/resource", headers={"X-API-Key": "key-c"})
    assert clock_probe.status_code == 200


def test_missing_api_key_is_rejected_without_consuming_budget(client):
    resp = client.get("/resource")
    assert resp.status_code == 401
    # The anonymous rejection must not have touched any bucket's budget.
    for _ in range(10):
        assert _get(client, "key-a").status_code == 200


def test_health_endpoint_is_exempt(client):
    for _ in range(15):
        resp = client.get("/health", headers={"X-API-Key": "key-a"})
        assert resp.status_code == 200


def test_limiter_is_usable_standalone(clock):
    limiter = FixedWindowRateLimiter(limit=3, window_seconds=30, clock=clock)
    assert all(limiter.check("k")[0] for _ in range(3))
    allowed, retry_after = limiter.check("k")
    assert not allowed and retry_after == 30
    clock.advance(31)
    allowed, retry_after = limiter.check("k")
    assert allowed and retry_after == 0
